INSERT INTO `questions` VALUES (1,'LISTENING','Some people think that universities should provide graduates with the knowledge and skills needed in the workplace. Others think that the true function of a university should be to give access to knowledge for its own sake, regardless of whether the course is useful to an employer. Discuss both views and give your opinion.','c240d561-6d5e-49df-a763-592d8b877c5f.png','','2026-07-21 18:13:34'),(2,'MULTIPLE_CHOICE','Thủ đô của Việt Nam là gì?',NULL,NULL,'2026-07-27 17:44:34'),(3,'LISTENING','Listen question test.','e4fee36e-41d3-4040-9230-22893fb92d1e.jpg',NULL,'2026-07-30 14:29:57'),(4,'MULTIPLE_CHOICE','Thủ đô của Việt Nam là thành phố nào?',NULL,'Hà Nội là thủ đô của nước CHXHCN Việt Nam.','2026-07-30 15:18:25'),(5,'TRUE_FALSE','Choose the correct synonym for \"ADVANTAGEOUS\":',NULL,'Trái Đất có dạng hình cầu hơi dẹt ở hai cực.','2026-07-30 15:18:25'),(6,'MULTIPLE_CHOICE','Which word best fits the blank: \"The government should ____ strict policies to combat climate change.\"',NULL,'Java, Kotlin và Scala đều biên dịch ra bytecode chạy trên JVM.','2026-07-30 15:18:25'),(7,'MULTIPLE_CHOICE','Summarize the main features and make comparisons where relevant for the given chart about global energy consumption.',NULL,'','2026-08-05 23:26:49'),(8,'ESSAY','quốc khánh nước việt nam vào ngày nào',NULL,'','2026-08-05 23:27:23'),(9,'FILL_BLANK','Xin chào Việt ...... ?',NULL,'','2026-08-05 23:28:12'),(10,'MULTIPLE_CHOICE','Thủ đô của Việt Nam là thành phố nào?',NULL,'Hà Nội là thủ đô của nước CHXHCN Việt Nam.','2026-08-05 23:28:23'),(11,'TRUE_FALSE','Trái Đất có hình vuông đúng hay sai?',NULL,'Trái Đất có dạng hình cầu hơi dẹt ở hai cực.','2026-08-05 23:28:23'),(12,'MULTIPLE_CHOICE','Chọn các ngôn ngữ lập trình chạy trên máy ảo JVM?',NULL,'Java, Kotlin và Scala đều biên dịch ra bytecode chạy trên JVM.','2026-08-05 23:28:23'),(13,'MULTIPLE_CHOICE','Thủ đô của Việt Nam là thành phố nào?',NULL,'Hà Nội là thủ đô của nước CHXHCN Việt Nam.